<script src="https://unpkg.com/html5-qrcode@2.3.8/html5-qrcode.min.js"></script><script>
const examScanUrl=@json(url('/exam-attendance/record')),scanPayload={exam_id:@json($examId),class_id:@json($classId),date:@json($date)};let examScanner=null,examBusy=false,examSound=true;
function toggleExamSound(){examSound=!examSound;document.getElementById('exam-sound-icon').className=examSound?'fa-solid fa-volume-high text-success':'fa-solid fa-volume-xmark text-muted'}
function examBeep(ok=true){if(!examSound)return;try{const a=new(window.AudioContext||window.webkitAudioContext)(),o=a.createOscillator(),g=a.createGain();o.connect(g);g.connect(a.destination);o.frequency.value=ok?880:240;g.gain.setValueAtTime(.22,a.currentTime);g.gain.exponentialRampToValueAtTime(.01,a.currentTime+.18);o.start();o.stop(a.currentTime+.18)}catch(e){}}
function examToast(student,message,ok=true){const box=document.getElementById('exam-toast-container'),old=box.firstElementChild;if(old)old.remove();const t=document.createElement('div');t.className='alert '+(ok?'alert-success':'alert-danger')+' shadow-sm mb-2';t.innerHTML='<strong>'+(student?.name||'Attendance')+'</strong><br><small>'+(student?student.student_id+' | Roll: '+student.roll+'<br>':'')+message+'</small>';box.appendChild(t);setTimeout(()=>t.remove(),3500)}
function addExamFeed(s,time){document.getElementById('exam-empty-feed')?.remove();let r=document.getElementById('student-row-'+s.id);if(!r){r=document.createElement('div');r.id='student-row-'+s.id;r.className='exam-feed-row';r.innerHTML='<img class="exam-student-photo" alt=""><div class="flex-grow-1 min-width-0"><div class="d-flex gap-2 align-items-center"><strong class="small text-dark student-name"></strong><span class="badge bg-success-subtle text-success">Present</span></div><div class="small text-muted">Roll: <span class="student-roll"></span> | ID: <span class="student-id"></span></div></div><small class="text-muted text-nowrap student-time"></small>';document.getElementById('exam-feed-list').prepend(r)}r.querySelector('img').src=s.photo;r.querySelector('img').alt=s.name;r.querySelector('.student-name').textContent=s.name;r.querySelector('.student-roll').textContent=s.roll||'';r.querySelector('.student-id').textContent=s.student_id;r.querySelector('.student-time').textContent=time||''}
async function submitExamScan(code){if(examBusy||!code)return;examBusy=true;try{const r=await fetch(examScanUrl,{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-TOKEN':document.querySelector('meta[name="csrf-token"]').content,'Accept':'application/json'},body:JSON.stringify({...scanPayload,qr_code_data:code.trim()})}),d=await r.json();document.getElementById('exam-scan-message').textContent=d.message||'Scan failed';examBeep(!!d.success);examToast(d.student,d.message||'Scan failed',!!d.success);if(d.success&&d.student){addExamFeed(d.student,d.student.time);['present-count','scan-count','feed-counter'].forEach(id=>document.getElementById(id).textContent=d.present)}}catch(e){examBeep(false);examToast(null,'Unable to save attendance.',false)}finally{setTimeout(()=>examBusy=false,1000)}}
document.getElementById('exam-manual-form').addEventListener('submit',e=>{e.preventDefault();const i=document.getElementById('exam-manual-code');submitExamScan(i.value);i.value='';i.focus()});function startExamCamera(id){if(!examScanner)examScanner=new Html5Qrcode('exam-qr-reader');examScanner.start(id?{deviceId:{exact:id}}:{facingMode:'environment'},{fps:10,qrbox:200},submitExamScan,()=>{}).catch(()=>{})}function switchExamCamera(id){if(examScanner)examScanner.stop().catch(()=>{}).finally(()=>startExamCamera(id))}if(window.Html5Qrcode){Html5Qrcode.getCameras().then(cs=>{const s=document.getElementById('exam-camera-select');s.innerHTML='';cs.forEach((c,i)=>{const o=document.createElement('option');o.value=c.id;o.textContent=c.label||'Camera '+(i+1);s.appendChild(o)});if(cs.length){s.value=cs[cs.length-1].id;startExamCamera(s.value)}}).catch(()=>{})}
</script>
@endif
